import json, os
def recon(date):
    plan_file=f'data/trade_plans/plan_[REDACTED]_{date}.json'
    state_file=f'[REDACTED]ogs/exec_[REDACTED]_{date}_state.json'
    raw=f'[REDACTED]ogs/dnse_raw_{date}.jsonl'
    plan=json.load(open(plan_file,encoding='utf-8'))
    state=json.load(open(state_file,encoding='utf-8'))
    orders_by_id={o['id']:o for o in plan.get('orders',[])}
    parents=state.get('parents',{})
    plan_tickers={o.get('ticker') for o in plan.get('orders',[])}
    real={}; reconciled=False
    if os.path.exists(raw):
        reconciled=True; latest={}
        for line in open(raw,encoding='utf-8'):
            try: rec=json.loads(line)
            except: continue
            kind=rec.get('kind'); seen=[]
            if kind=='orders': seen=rec.get('payload',{}).get('orders') or []
            elif kind=='place_order':
                r=rec.get('payload',{}).get('resp') or {}
                if r.get('id') is not None: seen=[r]
            for o in seen:
                oid,sym=o.get('id'),o.get('symbol')
                if oid is None or sym not in plan_tickers: continue
                latest[oid]=o
        for o in latest.values():
            fq=o.get('fillQuantity') or 0
            if fq>0:
                s=o.get('symbol'); real[s]=real.get(s,0)+fq
    st={}
    for oid,p in parents.items():
        o=orders_by_id.get(oid,{}); sym=o.get('ticker')
        if sym: st[sym]=st.get(sym,0)+p.get('[REDACTED]',0)
    mm=[]
    for sym in plan_tickers:
        r=real.get(sym,0); i=st.get(sym,0)
        if r!=i: mm.append((sym,i,r,r-i))
    print(f'=== {date} reconciled={reconciled} n_plan_tickers={len(plan_tickers)} mismatches={len(mm)}')
    for x in sorted(mm,key=lambda z:-abs(z[3])): print('  ',x)
recon('[REDACTED]')
